ALTER TABLE public.profiles ADD COLUMN is_active boolean NOT NULL DEFAULT true;
CREATE OR REPLACE FUNCTION public.is_membership_active(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id = _user_id AND is_active = true) $$;
GRANT EXECUTE ON FUNCTION public.is_membership_active(uuid) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.protect_membership_status() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF auth.role() IN ('authenticated','anon') AND ((TG_OP = 'INSERT' AND NEW.is_active = false) OR (TG_OP = 'UPDATE' AND NEW.is_active IS DISTINCT FROM OLD.is_active)) THEN RAISE EXCEPTION 'لا تملك صلاحية تعديل حالة العضوية مباشرة'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_membership_status BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_membership_status();
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.is_membership_active(_user_id) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE OR REPLACE FUNCTION public.is_super_admin(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(_user_id,'super_admin') $$;
CREATE OR REPLACE FUNCTION public.is_platform_agent(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(_user_id,'platform_agent') $$;
CREATE OR REPLACE FUNCTION public.is_company_admin(_user_id uuid,_company_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.is_membership_active(_user_id) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND company_id=_company_id AND role='company_admin') $$;
CREATE OR REPLACE FUNCTION public.is_company_staff(_user_id uuid,_company_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.is_membership_active(_user_id) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND company_id=_company_id AND role IN ('company_admin','agent')) $$;
CREATE OR REPLACE FUNCTION public.current_company_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT company_id FROM public.profiles WHERE id=auth.uid() AND is_active=true $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['companies','branches','tickets','ticket_updates','user_roles','platform_settings'] LOOP EXECUTE format('CREATE POLICY "active memberships only" ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (public.is_membership_active(auth.uid())) WITH CHECK (public.is_membership_active(auth.uid()))',t); END LOOP; END $$;
CREATE POLICY "active profile inserts" ON public.profiles AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (is_active=true);
CREATE POLICY "active profile updates" ON public.profiles AS RESTRICTIVE FOR UPDATE TO authenticated USING (public.is_membership_active(auth.uid())) WITH CHECK (public.is_membership_active(auth.uid()));
CREATE POLICY "active profile reads or own status" ON public.profiles AS RESTRICTIVE FOR SELECT TO authenticated USING (id=auth.uid() OR public.is_membership_active(auth.uid()));